type domainVectorKey interface {
	GetPublicKeyHex(compressed bool) string
	GeneratePublicKeyFromHex(compressed bool, hex string) error
	VerifySignature(message, signature []byte) (bool, error)
	SignWithContext(domain SigningDomain, data []byte) ([]byte, error)
	VerifyWithContext(domain SigningDomain, data, signature []byte) (bool, error)
}

func newDomainVectorKey(t *testing.T, keyType KeyType) domainVectorKey {
	t.Helper()
	switch keyType {
	case KeyTypeSecp256k1:
		return NewSecp256k1Key(sha256.New())
	case KeyTypeMlDSA87:
		return NewMLDSA87Key(sha256.New())
	case KeyTypeED25519:
		return NewED25519Key(sha256.New())
	case KeyTypeBLS12377:
		return NewBLS12377Key(sha256.New())
	}
	t.Fatalf("unknown key type %d", keyType)
	return nil
}

func seedDomainVectorKey(t *testing.T, v domainVector) domainVectorKey {
	t.Helper()
	key := newDomainVectorKey(t, v.keyType)
	seed := mustDomainVectorHex(t, v.seedHex)
	salt := mustDomainVectorHex(t, v.saltHex)
	var err error
	// The salted seed derivation is GenerateKeyFromSeed in the node and
	// RegenerateKeyFromSeed in the SDK.
	switch k := any(key).(type) {
	case interface{ RegenerateKeyFromSeed(seed, salt []byte) error }:
		err = k.RegenerateKeyFromSeed(seed, salt)
	case interface{ GenerateKeyFromSeed(seed, salt []byte) error }:
		err = k.GenerateKeyFromSeed(seed, salt)
	default:
		t.Fatalf("%T has no salted seed derivation", key)
	}
	if err != nil {
		t.Fatalf("%s seed derivation: %v", v.keyType, err)
	}
	return key
}

func mustDomainVectorHex(t *testing.T, h string) []byte {
	t.Helper()
	b, err := HexToBytes(h)
	if err != nil {
		t.Fatalf("HexToBytes: %v", err)
	}
	return b
}

func TestDomainSeparatedMessageVector(t *testing.T) {
	got, err := DomainSeparatedMessage("ul/test/v1", []byte("hello"))
	if err != nil {
		t.Fatalf("DomainSeparatedMessage: %v", err)
	}
	if want := mustDomainVectorHex(t, domainSeparatedMessageVectorHex); !bytes.Equal(got, want) {
		t.Fatalf("DomainSeparatedMessage = %s, want %s", BytesToHex(got), BytesToHex(want))
	}
}

func TestSigningDomainValues(t *testing.T) {
	seen := make(map[SigningDomain]bool)
	for _, d := range domainVectorDomainValues {
		if string(d.domain) != d.value {
			t.Fatalf("domain %q, want %q", d.domain, d.value)
		}
		if seen[d.domain] {
			t.Fatalf("domain %q appears twice", d.domain)
		}
		seen[d.domain] = true
	}
}

func TestDomainVectors(t *testing.T) {
	for _, v := range domainVectors {
		t.Run(v.keyType.String(), func(t *testing.T) {
			msg := mustDomainVectorHex(t, v.messageHex)
			sig := mustDomainVectorHex(t, v.signatureHex)

			verifier := newDomainVectorKey(t, v.keyType)
			if err := verifier.GeneratePublicKeyFromHex(true, v.publicKeyHex); err != nil {
				t.Fatalf("GeneratePublicKeyFromHex: %v", err)
			}
			if ok, err := verifier.VerifyWithContext(v.domain, msg, sig); err != nil || !ok {
				t.Fatalf("VerifyWithContext(%s) = (%v, %v), want (true, nil)", v.domain, ok, err)
			}
			other := DomainVote
			if v.domain == DomainVote {
				other = DomainBlock
			}
			if ok, _ := verifier.VerifyWithContext(other, msg, sig); ok {
				t.Fatalf("vector signed under %s verified under %s", v.domain, other)
			}
			if ok, _ := verifier.VerifySignature(msg, sig); ok {
				t.Fatalf("vector signed under %s verified under the empty context", v.domain)
			}

			seeded := seedDomainVectorKey(t, v)
			if got := seeded.GetPublicKeyHex(true); got != v.publicKeyHex {
				t.Fatalf("seed and salt derive public key %s, want %s", got, v.publicKeyHex)
			}
			if v.keyType == KeyTypeED25519 || v.keyType == KeyTypeBLS12377 {
				again, err := seeded.SignWithContext(v.domain, msg)
				if err != nil {
					t.Fatalf("SignWithContext: %v", err)
				}
				if got := BytesToHex(again); got != v.signatureHex {
					t.Fatalf("deterministic re-sign = %s, want %s", got, v.signatureHex)
				}
			}
		})
	}
}

// RFC 8032 section 7.2, Ed25519ctx with context "foo".
const (
	rfc8032Ed25519ctxSecretKeyHex = "0305334E381AF78F141CB666F6199F57BC3495335A256A95BD2A55BF546663F6"
	rfc8032Ed25519ctxPublicKeyHex = "DFC9425E4F968F7F0C29F0259CF5F9AED6851C2BB4AD8BFB860CFEE0AB248292"
	rfc8032Ed25519ctxMessageHex   = "F726936D19C800494E3FDAFF20B276A8"
	rfc8032Ed25519ctxSignatureHex = "55A4CC2F70A54E04288C5F4CD1E45A7BB520B36292911876CADA7323198DD87A8B36950B95130022907A7FB7C4E9B2D5F6CCA685A587B4B21F4B888E4E7EDB0D"
)

func TestEd25519ctxRFC8032Vector(t *testing.T) {
	const context = SigningDomain("foo")
	msg := mustDomainVectorHex(t, rfc8032Ed25519ctxMessageHex)

	signer := NewED25519Key(sha256.New())
	if err := signer.GeneratePrivateKeyFromHex(rfc8032Ed25519ctxSecretKeyHex + rfc8032Ed25519ctxPublicKeyHex); err != nil {
		t.Fatalf("GeneratePrivateKeyFromHex: %v", err)
	}
	sig, err := signer.SignWithContext(context, msg)
	if err != nil {
		t.Fatalf("SignWithContext: %v", err)
	}
	if got := BytesToHex(sig); got != rfc8032Ed25519ctxSignatureHex {
		t.Fatalf("SignWithContext = %s, want the RFC 8032 signature %s", got, rfc8032Ed25519ctxSignatureHex)
	}

	verifier := NewED25519Key(sha256.New())
	if err := verifier.GeneratePublicKeyFromHex(true, rfc8032Ed25519ctxPublicKeyHex); err != nil {
		t.Fatalf("GeneratePublicKeyFromHex: %v", err)
	}
	if ok, err := verifier.VerifyWithContext(context, msg, sig); err != nil || !ok {
		t.Fatalf("VerifyWithContext = (%v, %v), want (true, nil)", ok, err)
	}
	if ok, _ := verifier.VerifyWithContext(SigningDomain("bar"), msg, sig); ok {
		t.Fatal("the RFC 8032 signature verified under another context")
	}
}

func TestWriteDomainVectors(t *testing.T) {
	if os.Getenv("UL_WRITE_DOMAIN_VECTORS") != "1" {
		t.Skip("set UL_WRITE_DOMAIN_VECTORS=1 to print fresh domain vectors")
	}
	for _, v := range domainVectors {
		key := seedDomainVectorKey(t, v)
		sig, err := key.SignWithContext(v.domain, mustDomainVectorHex(t, v.messageHex))
		if err != nil {
			t.Fatalf("%s SignWithContext: %v", v.keyType, err)
		}
		t.Logf("%s\npublicKeyHex: %q\nsignatureHex: %q", v.keyType, key.GetPublicKeyHex(true), BytesToHex(sig))
	}
}
